  test('a strong PvP Artifact is removed without spending mana',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),artifact={id:'duel-blade',uid:'duel-blade-1',name:'Duel Blade',color:'red',type:'artifact',basic:{attack:3},strong:{attack:7}};Object.assign(p1,{q:0,r:0,hand:[artifact]});Object.assign(p2,{q:1,r:0});s.points.move=2;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});s=reduceGame(s,{type:'PVP_ATTEND',mode:'partial',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p1'});s=reduceGame(s,{type:'PVP_PLAY_CARD',uid:artifact.uid,mode:'strong',playerId:'p1'});expect(s.error).toBeNull();expect(s.pvp.attackPower).toBe(7);expect(s.players.find(player=>player.id==='p1').removed[0].uid).toBe(artifact.uid);});
