  test('a melee attacker may spend five damage to steal a public or wounded-Unit Artifact',()=>{let s=started('full-conquest'),p2=s.players.find(player=>player.id==='p2');p2.discard.push({id:'public-artifact',uid:'public-artifact-1',name:'Public Artifact',type:'artifact'});p2.hand.push({id:'hidden-artifact',uid:'hidden-artifact-1',name:'Hidden Artifact',type:'artifact'});p2.units=[{id:'wounded-unit',name:'Wounded Unit',wounded:true,banner:{id:'banner-captive',uid:'banner-captive-1',name:'Captive Banner',type:'artifact'}}];s.pvp={attackerId:'p1',defenderId:'p2',attendance:'partial',phase:'melee',stage:'damage',currentAttackerId:'p1',damageRemaining:15,attackElements:['physical']};s.phase='pvp-melee';s=reduceGame(s,{type:'PVP_STEAL_ARTIFACT',uid:'public-artifact-1',playerId:'p1'});expect(s.pvp.damageRemaining).toBe(10);expect(s.players.find(player=>player.id==='p1').discard.some(card=>card.uid==='public-artifact-1')).toBe(true);s=reduceGame(s,{type:'PVP_STEAL_ARTIFACT',uid:'banner-captive-1',playerId:'p1'});expect(s.pvp.damageRemaining).toBe(5);expect(s.players.find(player=>player.id==='p2').units[0].banner).toBeNull();expect(s.players.find(player=>player.id==='p1').discard.some(card=>card.uid==='banner-captive-1')).toBe(true);s=reduceGame(s,{type:'PVP_STEAL_ARTIFACT',uid:'hidden-artifact-1',playerId:'p1'});expect(s.error).toMatch(/discard pile, play area, or a Wounded Unit/i);expect(s.players.find(player=>player.id==='p2').hand.some(card=>card.uid==='hidden-artifact-1')).toBe(true);});
  test('PvP victory Fame always includes the base point when the winner has a lower level',()=>{let s=started('full-conquest');const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2');Object.assign(p1,{q:0,r:0,level:1,fame:20});Object.assign(p2,{q:0,r:0,level:3,fame:10});s.pvp={attackerId:'p1',defenderId:'p2',attendance:'partial',phase:'melee',stage:'damage',currentAttackerId:'p1',damageRemaining:9,attackElements:['physical']};s.phase='pvp-melee';s=reduceGame(s,{type:'PVP_FORCE_RETREAT',q:1,r:-1,playerId:'p1'});expect(s.error).toBeNull();expect(s.players.find(player=>player.id==='p1').fame).toBe(25);expect(s.players.find(player=>player.id==='p1').pvpWins).toBe(1);});
  test('PvP cannot force a hero to retreat into a rival keep',()=>{let s=started('full-conquest');const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),hex=s.map.find(item=>item.q===1&&item.r===-1);Object.assign(p1,{q:0,r:0});Object.assign(p2,{q:0,r:0});Object.assign(hex,{revealed:true,site:'keep',conquered:true,ownerId:'p1',enemy:null,enemies:[]});s.pvp={attackerId:'p1',defenderId:'p2',attendance:'partial',phase:'melee',stage:'damage',currentAttackerId:'p1',damageRemaining:9,attackElements:['physical']};s.phase='pvp-melee';s=reduceGame(s,{type:'PVP_FORCE_RETREAT',q:1,r:-1,playerId:'p1'});expect(s.error).toMatch(/safe adjacent/i);expect([p2.q,p2.r]).toEqual([0,0]);});
  test('final scoring includes categories and wound penalties',()=>{const s=createGame();s.player.fame=10;s.player.wounds=2;s.player.hand.push({id:'wound',uid:'score-w1'},{id:'wound',uid:'score-w2'});s.player.units=[{level:2}];const score=calculateScore(s);expect(score.players[0].categories.wounds).toBe(-4);expect(score.players[0].categories.leadership).toBe(2);expect(score.players[0].total).toBe(8);});
  test('scoring values Spells, Advanced Actions, and wounded Units correctly',()=>{const s=createGame();s.player.deck.push({id:'score-spell',type:'spell'},{id:'score-action',type:'advanced'});s.player.units=[{level:3,wounded:true},{level:2,wounded:false}];const row=calculateScore(s).players[0];expect(row.categories.knowledge).toBe(3);expect(row.categories.leadership).toBe(3);});
  test('tied achievement leaders gain one while the uniquely most wounded loses three',()=>{const state=createMultiplayerGame(lobby('full-conquest'),77);const [one,two]=state.players;one.units=[{level:2,wounded:false}];two.units=[{level:2,wounded:false}];one.hand.push({id:'wound',uid:'score-wound'});const score=calculateScore(state),p1=score.players.find(row=>row.playerId==='p1'),p2=score.players.find(row=>row.playerId==='p2');expect(p1.categories.leadership).toBe(2);expect(p1.categories.achievements).toBe(-2);expect(p2.categories.achievements).toBe(1);});
  test('city leaders score seven plus the unique city title',()=>{const state=createMultiplayerGame(lobby('full-conquest'),77),city=state.map.find(hex=>hex.site==='city');city.conquered=true;city.ownerId='p1';const score=calculateScore(state),p1=score.players.find(row=>row.playerId==='p1');expect(p1.categories.city).toBe(7);expect(p1.categories.achievements).toBe(5);});
  test('only owned keeps and participated cities increase a player hand limit',()=>{const drawNear=(site,ownerId,conquerors=[])=>{let s=started('full-conquest'),p1=s.players.find(player=>player.id==='p1'),hex=s.map.find(item=>item.site===site);Object.assign(p1,{q:hex.q-1,r:hex.r,hand:[],discard:[],deck:Array.from({length:10},(_,index)=>({id:`test-${index}`,uid:`test-${index}`})),keeps:2,emptyHandPassAllowed:true});Object.assign(hex,{revealed:true,conquered:true,ownerId,conquerors});s=reduceGame(s,{type:'END_TURN',playerId:'p1'});return s.players.find(player=>player.id==='p1').hand.length;};expect(drawNear('keep','p2')).toBe(5);expect(drawNear('keep','p1')).toBe(7);expect(drawNear('city','p2',['p1','p2'])).toBe(6);expect(drawNear('city','p1',['p1','p2'])).toBe(7);});
  test('a player may pass through another hero on an ordinary space',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);const p2=s.players.find(player=>player.id==='p2');Object.assign(p2,{q:0,r:-1});s.points.move=99;expect(legalMoves(s).some(hex=>hex.q===0&&hex.r===-1)).toBe(true);s=reduceGame(s,{type:'MOVE',q:0,r:-1,playerId:'p1'});expect(s.error).toBeNull();expect(legalMoves(s).some(hex=>hex.q===-1&&hex.r===0)).toBe(true);s=reduceGame(s,{type:'MOVE',q:-1,r:0,playerId:'p1'});expect(s.phase).toBe('action');expect([s.player.q,s.player.r]).toEqual([-1,0]);});
  test('ending on another hero forces backtracking and one Wound per space',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);Object.assign(s.players.find(player=>player.id==='p2'),{q:1,r:0});s.points.move=99;s=reduceGame(s,{type:'MOVE',q:1,r:0,playerId:'p1'});s.player.cardsPlayedThisTurn=1;s=reduceGame(s,{type:'END_TURN',playerId:'p1'});const p1=s.players.find(player=>player.id==='p1');expect([p1.q,p1.r]).toEqual([0,0]);expect(p1.wounds).toBe(1);expect(p1.hand.filter(card=>card.id==='wound')).toHaveLength(1);expect(s.log.some(entry=>/forced withdrawal/i.test(entry.message))).toBe(true);});
  test('an undefended rival keep draws a fortified half-Fame garrison and transfers ownership',()=>{let s=started('full-conquest');s.map.forEach(hex=>{hex.revealed=true;if(['rampaging','draconum'].includes(hex.site)){hex.enemy=null;hex.enemies=[];}});const keep=s.map.find(hex=>hex.site==='keep'),p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),greyCount=s.enemyDecks.grey.length;Object.assign(keep,{conquered:true,ownerId:'p2',enemy:null,enemies:[]});Object.assign(p1,{q:keep.q-1,r:keep.r,keeps:0});p2.keeps=1;s.points.move=99;s=reduceGame(s,{type:'START_COMBAT',q:keep.q,r:keep.r,playerId:'p1'});const garrison=s.combat.enemies.find(enemy=>enemy.uid.startsWith('rival-keep-'));expect(garrison.siteFortified).toBe(true);expect(garrison.fame).toBe(Math.ceil(s.combat.rivalKeepToken.fame/2));expect(s.enemyDecks.grey).toHaveLength(greyCount-1);s=reduceGame(s,{type:'FINISH_RANGED',playerId:'p1'});for(const enemy of [...s.combat.blockEnemies]){s.points.block=99;s=reduceGame(s,{type:'BLOCK_ENEMY',targetId:enemy.uid,playerId:'p1'});}s=reduceGame(s,{type:'FINISH_BLOCK',playerId:'p1'});s.points.attack=99;s=reduceGame(s,{type:'RESOLVE_ATTACK',targetIds:s.combat.enemies.map(enemy=>enemy.uid),playerId:'p1'});expect(s.map.find(hex=>hex.q===keep.q&&hex.r===keep.r).ownerId).toBe('p1');expect(s.players.find(player=>player.id==='p1').keeps).toBe(1);expect(s.players.find(player=>player.id==='p2').keeps).toBe(0);expect(s.enemyDecks.grey).toHaveLength(greyCount);});
  test('a rival keep occupied by its owner must be assaulted through PvP',()=>{let s=started('full-conquest');s.map.forEach(hex=>{hex.revealed=true;if(['rampaging','draconum'].includes(hex.site)){hex.enemy=null;hex.enemies=[];}});const keep=s.map.find(hex=>hex.site==='keep'),p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2');Object.assign(keep,{conquered:true,ownerId:'p2',enemy:null,enemies:[]});Object.assign(p1,{q:keep.q-1,r:keep.r});Object.assign(p2,{q:keep.q,r:keep.r});s.points.move=99;s=reduceGame(s,{type:'START_COMBAT',q:keep.q,r:keep.r,playerId:'p1'});expect(s.error).toMatch(/initiate PvP/i);s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});expect(s.phase).toBe('pvp-attend');expect(s.players.find(player=>player.id==='p1').reputation).toBe(-1);});
  test('city shields survive partial assaults and the player with most shields leads',()=>{let s=started('full-conquest');s.map.forEach(hex=>{hex.revealed=true;if(['rampaging','draconum'].includes(hex.site)){hex.enemy=null;hex.enemies=[];}});const city=s.map.find(hex=>hex.site==='city'),p1=s.players.find(player=>player.id==='p1');Object.assign(p1,{q:city.q-1,r:city.r});s.points.move=99;s=reduceGame(s,{type:'START_COMBAT',q:city.q,r:city.r,playerId:'p1'});s=reduceGame(s,{type:'FINISH_RANGED',playerId:'p1'});for(const enemy of [...s.combat.blockEnemies]){s.points.block=99;s=reduceGame(s,{type:'BLOCK_ENEMY',targetId:enemy.uid,playerId:'p1'});}s=reduceGame(s,{type:'FINISH_BLOCK',playerId:'p1'});const first=s.combat.enemies[0].uid;s.points.attack=99;s=reduceGame(s,{type:'RESOLVE_ATTACK',targetIds:[first],playerId:'p1'});s=reduceGame(s,{type:'END_COMBAT',playerId:'p1'});expect(s.map.find(hex=>hex.q===city.q&&hex.r===city.r).cityShields.p1).toBe(1);const discard=s.players.find(player=>player.id==='p1').hand[0].uid;s=resolveLevelUps(reduceGame(s,{type:'END_TURN',discardUids:[discard],playerId:'p1'}));const p2=s.players.find(player=>player.id==='p2');Object.assign(p2,{q:city.q-1,r:city.r});s.points.move=99;s=reduceGame(s,{type:'START_COMBAT',q:city.q,r:city.r,playerId:'p2'});s=reduceGame(s,{type:'FINISH_RANGED',playerId:'p2'});for(const enemy of [...s.combat.blockEnemies]){s.points.block=99;s=reduceGame(s,{type:'BLOCK_ENEMY',targetId:enemy.uid,playerId:'p2'});}s=reduceGame(s,{type:'FINISH_BLOCK',playerId:'p2'});s.points.attack=99;s=reduceGame(s,{type:'RESOLVE_ATTACK',targetIds:s.combat.enemies.map(enemy=>enemy.uid),playerId:'p2'});const conquered=s.map.find(hex=>hex.q===city.q&&hex.r===city.r);expect(conquered.cityShields).toEqual({p1:1,p2:2});expect(conquered.ownerId).toBe('p2');});
  test('cooperative team score uses lower Fame, best achievements, worst wounds, and dummy timing',()=>{const state=createMultiplayerGame(lobby('cooperative-conquest'),77),[one,two]=state.players;one.fame=10;two.fame=6;one.deck.push({id:'team-spell',type:'spell'});two.units=[{level:3,wounded:false}];one.hand.push({id:'wound',uid:'team-wound'});const score=calculateScore(state);expect(score.teamTotal).toBe(30);expect(score.scenarioBonus.dummy).toBe(16);expect(score.scenarioBonus.noAnnouncement).toBe(5);expect(score.winner).toBeNull();});
