  test('units can absorb damage, remain wounded, and consume Heal to recover',()=>{let s=createGame();s.player.units=[{id:'guard',name:'Guard',level:1,armor:3,ability:{block:1},spent:false,wounded:false}];s.player.q=1;s.player.r=0;s=act(s,'START_COMBAT',{q:2,r:-1});s=act(s,'RESOLVE_RANGED');s=act(s,'RESOLVE_BLOCK');s=act(s,'ASSIGN_DAMAGE_UNIT',{id:'guard'});s=act(s,'RESOLVE_DAMAGE');expect(s.player.units[0].wounded).toBe(true);expect(s.player.wounds).toBe(1);s.phase='action';s.points.heal=1;s=act(s,'SPEND_HEAL',{unitId:'guard'});expect(s.player.units[0].wounded).toBe(false);expect(s.points.heal).toBe(0);});
  test('a poisoned Unit must pay its level twice to remove both Wounds',()=>{let s=createGame();s.player.units=[{id:'guard',name:'Guard',level:2,armor:3,ability:{block:1},spent:false,wounded:true,woundCount:2}];s.points.heal=4;s=act(s,'SPEND_HEAL',{unitId:'guard'});expect(s.player.units[0]).toMatchObject({wounded:true,woundCount:1});expect(s.points.heal).toBe(2);s=act(s,'SPEND_HEAL',{unitId:'guard'});expect(s.player.units[0]).toMatchObject({wounded:false,woundCount:0});expect(s.points.heal).toBe(0);});
  test('a resistant Unit that absorbs an attack cannot receive another in the same combat',()=>{let s=createGame();s.player.units=[{id:'golem',name:'Golem',level:2,armor:5,resistances:['fire'],spent:false,wounded:false}];s.phase='combat-damage';s.combat={damageQueue:[{id:'fire-a',attack:4,traits:['fire']},{id:'fire-b',attack:4,traits:['fire']}],damageUnits:[],damageAssignedUnitIds:[],enemies:[],defeatedIds:[],blockedIds:[],woundsTaken:0};s=act(s,'ASSIGN_DAMAGE_UNIT',{id:'golem'});s=act(s,'RESOLVE_DAMAGE');expect(s.player.units[0].wounded).toBe(false);s=act(s,'ASSIGN_DAMAGE_UNIT',{id:'golem'});expect(s.error).toMatch(/already assigned/i);});
