  test('scenario completion grants every player, including the conqueror, one new final turn',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);const cities=s.map.filter(hex=>hex.site==='city');cities[0].conquered=true;cities[0].enemy=null;Object.assign(s.players.find(player=>player.id==='p1'),{q:cities[1].q-1,r:cities[1].r});s.points.move=9;s.points.siege=99;s.points.attack=99;s=reduceGame(s,{type:'START_COMBAT',q:cities[1].q,r:cities[1].r,playerId:'p1'});s=reduceGame(s,{type:'RESOLVE_RANGED',playerId:'p1'});for(const enemy of [...s.combat.blockEnemies]){s.points.block=99;s=reduceGame(s,{type:'BLOCK_ENEMY',targetId:enemy.uid,playerId:'p1'});}s=reduceGame(s,{type:'FINISH_BLOCK',playerId:'p1'});s.points.attack=99;s=reduceGame(s,{type:'RESOLVE_ATTACK',targetIds:s.combat.enemies.map(enemy=>enemy.uid),playerId:'p1'});expect(s.status).toBe('playing');expect(s.scenarioEndTurnsRemaining).toBe(2);let discardUid=s.players.find(player=>player.id==='p1').hand[0].uid;s=resolveLevelUps(reduceGame(s,{type:'END_TURN',discardUids:[discardUid],playerId:'p1'}));expect(s.scenarioEndTurnsRemaining).toBe(2);discardUid=s.players.find(player=>player.id==='p2').hand[0].uid;s=resolveLevelUps(reduceGame(s,{type:'END_TURN',discardUids:[discardUid],playerId:'p2'}));expect(s.status).toBe('playing');discardUid=s.players.find(player=>player.id==='p1').hand[0].uid;s=resolveLevelUps(reduceGame(s,{type:'END_TURN',discardUids:[discardUid],playerId:'p1'}));expect(s.status).toBe('won');expect(s.scoring.players).toHaveLength(2);});
  test('players may enter an occupied non-portal space before resolving movement',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);Object.assign(s.players.find(player=>player.id==='p2'),{q:1,r:0});s.points.move=9;s=reduceGame(s,{type:'MOVE',q:1,r:0,playerId:'p1'});expect(s.error).toBeNull();expect([s.player.q,s.player.r]).toEqual([1,0]);});
  test('movement between two adjacent spaces provokes a rampaging enemy into combat',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);const p1=s.players.find(player=>player.id==='p1'),rampager=s.map.find(hex=>hex.site==='rampaging');Object.assign(p1,{q:1,r:0});s.points.move=9;s=reduceGame(s,{type:'MOVE',q:1,r:-1,playerId:'p1'});expect(s.phase).toBe('combat-ranged');expect(s.combat.kind).toBe('provoked');expect(s.combat.enemies.map(enemy=>enemy.uid)).toContain(rampager.enemy.uid);const moved=s.players.find(player=>player.id==='p1');expect([moved.q,moved.r]).toEqual([1,-1]);});
  test('defeating a provoked rampager removes its source token and grants reputation',()=>{let s=createGame();const rampager=s.map.find(hex=>hex.site==='rampaging');s.player.q=1;s.player.r=0;s.points.move=9;s=act(s,'MOVE',{q:1,r:-1});const fame=s.combat.enemy.fame;s.points.ranged=99;s=act(s,'RESOLVE_RANGED',{targetIds:s.combat.enemies.map(enemy=>enemy.uid)});expect(s.phase).toBe('action');expect(s.map.find(hex=>hex.q===rampager.q&&hex.r===rampager.r).enemy).toBeNull();expect(s.player.fame).toBe(fame);expect(s.player.reputation).toBe(1);});
